cfg = repo.read("config.json", missing_ok=True)
if cfg == None:
    # search for config.json in subdirs
    hits = repo.search("timeout_ms", glob="**/config.json")
    return {"found": False, "hits": [(h.path, h.line, h.text) for h in hits]}
return {"found": True, "content": cfg}
